 const hash=(s,n=0)=>{let x=Math.imul(((s.seed||0)^n)>>>0,2654435761);x=Math.imul(x^(x>>>16),2246822507);return(x^(x>>>13))>>>0},bound=x=>Math.max(0,Math.min(100,x));
 const is=s=>s.race!==0,profile=s=>models[mapping[typeof s==='number'?s:s.race]],slot=s=>s.socialOrigin?.origin??hash(s,0x71a43)%8;
 function ensure(s,fresh=false){if(!is(s))return null;if(!s.socialOrigin){const m=profile(s),origin=slot(s);s.socialOrigin={version:1,model:m.id,origin,resources:28+hash(s,7201)%58,access:25+hash(s,7202)%62,duty:20+hash(s,7203)%66,voice:18+hash(s,7204)%53,migrated:!fresh,role:null,lastReview:Math.floor(s.age||0),history:[]}}return s.socialOrigin}
 function label(s){if(!is(s))return CLASSES[s.rank];const a=ensure(s),m=profile(s);return a.role||m.origins[a.origin]}
 function note(s){if(!is(s))return s.heritage?.note||s.family;return profile(s).note+' · '+local[s.race]+(s.heritage?.familyId==='hero'?' · สายของคุณมีผู้เคยร่วมช่วยถิ่นจากภัยใหญ่':s.heritage?.familyId==='demonKing'?' · สายของคุณค้ำตราแห่งบัลลังก์และมีพันธะต่อหัวเมือง':'')}
 function home(s){return is(s)?profile(s).home:LifeContent.homes[s.rank]}
 function metrics(s){const a=ensure(s),m=profile(s),l=s.lifeChoices||{},native=typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s),resources=native?s.raceDrives.resource:a.resources;return {resources:Math.round(resources),access:Math.round(bound(a.access+(l.localTrust-40||0)*.2+((l.classStanding??a.voice)-a.voice)*.155)),duty:Math.round(a.duty),voice:Math.round(bound(a.voice+(s.fame||0)*.18+(l.localTrust-40||0)*.2+((l.classStanding??a.voice)-a.voice)*.15)),m}}
 function birth(s){if(!is(s))return;const a=ensure(s,true),m=profile(s);if(s.heritage?.familyId==='demonKing'&&Species.isDemon(s.race)){a.origin=7;a.access=88;a.duty=92;a.voice=65}if(s.heritage?.familyId==='dragonCourt'&&[9,36].includes(s.race)){a.origin=6;a.access=83;a.duty=79}if(s.raceDrives)s.raceDrives.resource=a.resources;s.household.title=m.group;s.household.originNote=note(s);s.family=m.group;if(s.heritage)s.heritage.note=note(s);decorateKin(s);if(s.lifeChoices){s.lifeChoices.classStanding=a.voice;s.lifeChoices.localTrust=35+a.access*.25}}
 function decorateKin(s,only){if(!is(s))return;for(const member of s.household?.members||[]){if(only&&only!==member.id||member.race===0)continue;const m=profile(member.race),p=Ecology.profile(member.race),job=m.jobs[hash(s,member.name.length+member.race*113)%m.jobs.length];member.adultOccupation=job;member.nativeOccupation=job;const age=Engine.ageEquivalent(FamilyWorld.age(s,member),member.race);member.occupation=age<18?'กำลังเรียนรู้วิถีของ'+m.group:job;if(p.origin==='spore')member.role=member.id==='guardian'?'ใยต้นทาง · ผู้เพาะหัวเชื้อ':member.id==='partner'?'คู่เชื่อมใย':member.id.startsWith('child-')?'หน่อร่วมใย':'สมาชิกเครือใย';else if(['awaken','crystal','sand','ink','ember','bud','seed'].includes(p.origin))member.role=member.id==='guardian'?'ผู้ประคองต้นกำเนิด':member.id==='partner'?'คู่ผูกพันที่เลือกกัน':member.id.startsWith('child-')?'สมาชิกอ่อนที่รับดูแล':'ผู้ร่วม'+m.group;else if(['egg','roe'].includes(p.origin)&&member.id==='guardian')member.role='ผู้เฝ้าแหล่งฟักและแนวพัก';if(p.strict)member.trait='จำ'+p.sense+'และส่งสัญญาณให้กลุ่มก่อนเข้าถิ่น'}}
 function resourcesText(s){const x=metrics(s),name=profile(s).res;return name+(x.resources<35?'มีจำกัด':x.resources<65?'พอแบ่งใช้':'มีส่วนสำรอง')}
 function finance(s){const a=ensure(s),m=profile(s);return {personal:Math.round((80+a.resources*a.access*.35)*m.factor),fund:Math.round((1500+a.resources*a.resources*13)*m.factor),wage:Math.round((30000+a.resources*550+a.access*260)*m.factor)}}
 function familyBill(s,children,monthly){return Math.round(monthly*3*(1.65+children*.25))}
 function allowance(s){const a=metrics(s);return Math.round(20+a.resources*.7+a.access*.35)}
 function living(s,e,owned,fallback){const m=profile(s),p=Ecology.profile(s),base={...fallback};if(['core','undead'].includes(m.id)){base.food=m.id==='core'?220:180;base.utilities=180;base.health=240;base.needs=210}if([27,46,53].includes(s.race)){base.food=800;base.health=460;base.housing=owned?900:e.housing==='family'?650:1850}if(p.water){base.utilities=210;base.transport=140;base.health=300}return base}
